import { NextRequest, NextResponse } from "next/server";
import { put } from "@vercel/blob";
import { prisma } from "@/lib/prisma";

// TEMPORARY one-off route — diversifies the regular-set photos: gives each
// of the 12 products a distinct primary etrog reference photo (instead of
// reusing one photo across all 4 hiddur levels of a variety) plus a shared
// secondary "included items" shot of the lulav packaging. Gated by a secret
// query param. Delete this file (and redeploy) immediately after one use.
const SECRET = "f3a8c1e6b2d9047ea5c8b1f4d6e0a3c7b9f2d5e8a1c4b7f0d3e6a9c2b5f8e1d4";

const PHOTO_1 = "";
const PHOTO_3 = "";
const PHOTO_4 = "";
const PHOTO_5 = "";
const PHOTO_6 = "";
const PHOTO_7 = "";
const PHOTO_8 = "";

async function uploadOnce(pathname: string, base64: string, contentType: string) {
  const buffer = Buffer.from(base64, "base64");
  const blob = await put(pathname, buffer, { access: "public", contentType });
  return blob.url;
}

async function setImages(slug: string, urls: string[]) {
  const set = await prisma.productSet.findUnique({ where: { slug } });
  if (!set) return `MISSING SLUG: ${slug}`;
  await prisma.setMedia.deleteMany({ where: { setId: set.id } });
  for (let i = 0; i < urls.length; i++) {
    await prisma.setMedia.create({
      data: { setId: set.id, type: "IMAGE", url: urls[i], sortOrder: i },
    });
  }
  return `${slug}: set ${urls.length} images`;
}

export async function GET(req: NextRequest) {
  const secret = req.nextUrl.searchParams.get("secret");
  if (secret !== SECRET) {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  const log: string[] = [];

  const url1 = await uploadOnce(`sets/variety-refs/temani-${Date.now()}.jpg`, PHOTO_1, "image/jpeg");
  const url3 = await uploadOnce(`sets/variety-refs/moroccan-a-${Date.now()}.jpg`, PHOTO_3, "image/jpeg");
  const url4 = await uploadOnce(`sets/variety-refs/moroccan-b-${Date.now()}.jpg`, PHOTO_4, "image/jpeg");
  const url5 = await uploadOnce(`sets/variety-refs/lulav-box-${Date.now()}.jpg`, PHOTO_5, "image/jpeg");
  const url6 = await uploadOnce(`sets/variety-refs/moroccan-c-${Date.now()}.jpg`, PHOTO_6, "image/jpeg");
  const url7 = await uploadOnce(`sets/variety-refs/regular-${Date.now()}.jpg`, PHOTO_7, "image/jpeg");
  const url8 = await uploadOnce(`sets/variety-refs/moroccan-d-${Date.now()}.jpg`, PHOTO_8, "image/jpeg");
  log.push("uploaded 7 fresh blobs");

  log.push(await setImages("regular-kosher", [url7, url5]));
  log.push(await setImages("regular-mehadrin", [url7, url5]));
  log.push(await setImages("regular-mehadrin-min-hamehadrin", [url7, url5]));
  log.push(await setImages("regular-diamond", [url7, url5]));

  log.push(await setImages("temani-kosher", [url1, url5]));
  log.push(await setImages("temani-mehadrin", [url1, url5]));
  log.push(await setImages("temani-mehadrin-min-hamehadrin", [url1, url5]));
  log.push(await setImages("temani-diamond", [url1, url5]));

  log.push(await setImages("moroccan-kosher", [url8, url5]));
  log.push(await setImages("moroccan-mehadrin", [url3, url5]));
  log.push(await setImages("moroccan-mehadrin-min-hamehadrin", [url4, url5]));
  log.push(await setImages("moroccan-diamond", [url6, url5]));

  return NextResponse.json({ ok: true, log });
}
